input.command:
cd "$ARCHON_HORIZON_ROOT" && for attempt in 1 2 3 4 5; do
  timeout 60 "$HORIZON_GIT" read-tree HEAD 2>/dev/null || { sleep 3; continue; }
  timeout 60 "$HORIZON_GIT" add -- MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Picard/DualNumberChartTriviality.lean 2>/dev/null || { sleep 3; continue; }
  if timeout 120 "$HORIZON_GIT" commit -q -F /tmp/msg_gen.txt 2>/tmp/cerr.txt; then echo "LANDED on attempt $attempt"; break; else echo "attempt $attempt failed:"; tail -3 /tmp/cerr.txt; sleep 4; fi
done; timeout 60 "$HORIZON_GIT" log --oneline -1
